// Get all data from different sources
const allInputs = $input.all();
const calendarEvents = allInputs.find(b => b.json.calendarEvents)?.json.calendarEvents || [];
const emails = allInputs.find(b => b.json.emails)?.json.emails || [];
const commits = allInputs.find(b => b.json.commits)?.json.commits || [];
const prs = allInputs.find(b => b.json.prs)?.json.prs || [];

// Format calendar events
const confirmed = calendarEvents.filter(e => e.status === 'confirmed');

const calendarSummary = confirmed.map(event => ({
  time: event.start?.dateTime || 'No time',
  title: event.summary || 'No title',
  attendees: event.attendees?.length || 0,
  description: event.description || 'No description',
  duration: DateTime.fromISO(event.end.dateTime).diff(DateTime.fromISO(event.start.dateTime), 'hours').hours
}));

// Format emails (filter out unimportant ones)
const importantEmails = emails
  .filter(email => 
    email.From && 
    !email.From.toLowerCase().includes('noreply') && 
    !email.Subject?.toLowerCase().includes('newsletter')
  )
  .slice(0, 20)
  .map(email => ({
    from: email.From,
    subject: email.Subject || 'No subject',
    snippet: email.snippet?.substring(0, 100) || ''
  }));

const commitArray = Array.isArray(commits) ? commits : [commits];
const prsArray = Array.isArray(prs) ? prs : [prs];
// Format GitHub activity
const githubActivity = {
  commits: commitArray.map(commit => ({
    message: commit.commit?.message || 'No message'
  })) || [],
  pullRequests: prsArray.map(pr => ({
    title: pr.title,
    repo: pr.head.repo?.name || 'Unknown repo',
    state: pr.state
  })) || []
};

// Create summary object
const summary = {
  date: $('Set Variables').first().json.today,
  calendar: {
    totalEvents: calendarSummary.length,
    events: calendarSummary
  },
  emails: {
    totalReceived: emails.length,
    important: importantEmails
  },
  github: githubActivity
};

return [{ json: summary }];

const input = $input.all();

const transformed = input.map(item => {
  const text = item.json["content.parts[0].text"];


  if (!text || typeof text !== "string") {
    return {
      keys: {
        calendar: ['emptystring'],
        emails: ['emptystring'],
        github: ['emptystring']
      }
    };
  }

  try {
    const parsedData = JSON.parse(text);


    const keys = {};

    if (parsedData.calendar?.events?.[0]?.title && parsedData.calendar?.events?.[0]?.time) {
      keys.calendar = {
         details: {
          Title: parsedData.calendar.events[0].title,
          Time : parsedData.calendar.events[0].time
             }
         };
    } else {
      keys.calendar = ['emptystring'];
    }

 if (
  parsedData.emails?.important?.[0]?.subject &&
  parsedData.emails?.important?.[0]?.from &&
  parsedData.emails?.important?.[0]?.snippet
) {
  const snippetRaw = parsedData.emails.important[0].snippet;
  const snippet = snippetRaw.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();

  keys.emails = {
   /* list: [
      parsedData.emails.important[0].subject,
      parsedData.emails.important[0].from,
      snippet
    ], */
    details: {
      Subject: parsedData.emails.important[0].subject,
      From: parsedData.emails.important[0].from,
      Snippet: snippet
    }
  };
} else {
  keys.emails = {
    list: ['emptystring'],
    details: {
      Subject: 'emptystring',
      From: 'emptystring',
      Snippet: 'emptystring'
    }
  };
}


    keys.github = ['emptystring'];

    return { keys };

  } catch (error) {
    return {
      keys: {
        calendar: ['emptystring'],
        emails: ['emptystring'],
        github: ['emptystring']
      }
    };
  }
});

return transformed;

// Get today's date in yyyy-MM-dd format
const now = new Date().toISOString().split('T')[0];
const input = $input.all();

let rows = [];

input.forEach(item => {
  const data = item.json;

  // Calendar
  if (data["keys.calendar"]) {
    rows.push({
      Date: now,
      Type: "Calendar",
      Value: data["keys.calendar"]
    });
  }

  // Emails
  if (data["keys.emails"]) {
    const email = data["keys.emails"];
    let emailString = [];
    if (email.Subject) emailString.push(`Subject: ${email.Subject}`);
    if (email.From) emailString.push(`From: ${email.From}`);
    if (email.Snippet) emailString.push(`Message: ${email.Snippet}`);
    rows.push({
      Date: now,
      Type: "Email",
      Value: emailString.join(" | ")
    });
  }

  // Github
  if (data["keys.github"]) {
    rows.push({
      Date: now,
      Type: "Github",
      Value: data["keys.github"]
    });
  }
});

// Sort rows by Type order: Calendar → Email → Github
const typeOrder = { "Calendar": 1, "Email": 2, "Github": 3 };
rows.sort((a, b) => typeOrder[a.Type] - typeOrder[b.Type]);

return rows.map(r => ({ json: r }));
